#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using u64 = unsigned long long;

constexpr int MAX_N = 250005, MAX_M = 1 << 17, MAX_D = 18;

int P;

int mod_pow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = (i64)res * base % P;
        base = (i64)base * base % P;
        exp >>= 1;
    }
    return res;
}

int L, K, fact[MAX_N], n, m, mask[20], inv_fact[MAX_N], popcnt[MAX_N];
i64 s_a[MAX_D][MAX_M], s_c[MAX_D][MAX_M];
u64 d_p[MAX_D][MAX_M], t[MAX_D][MAX_M];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> K >> P;

    fact[0] = 1;
    for (int i = 1; i <= L; ++i) {
        fact[i] = (i64)fact[i - 1] * i % P;
        popcnt[i] = popcnt[i >> 1] + (i & 1);
    }

    i64 total = mod_pow(K, L);
    if (L & 1) {
        cout << total << '\n';
        return 0;
    }

    inv_fact[L] = mod_pow(fact[L], P - 2);
    for (int i = L; i > 0; --i) {
        inv_fact[i - 1] = (i64)inv_fact[i] * i % P;
    }

    for (int i = 1; (1 << i) <= L; ++i) {
        if (L >> i & 1) mask[n++] = 1 << i;
    }

    m = 1 << n;

    for (int i = 0; i < m; ++i) {
        int sum = 0;
        for (int j = 0; j < n; ++j) {
            if (i >> j & 1) sum += mask[j];
        }
        s_a[popcnt[i]][i] = inv_fact[sum];
    }

    for (int t_idx = 0; t_idx <= n; ++t_idx) {
        i64* arr = s_a[t_idx];
        for (int len = m; len >= 2; len >>= 1) {
            for (int j = 0, step = len >> 1; j < m; j += len) {
                for (int k = 0; k < step; ++k) {
                    arr[j + k + step] += arr[j + k];
                }
            }
        }
        for (int j = 0; j < m; ++j) arr[j] %= P;
    }

    for (int t_idx = 0; t_idx <= n; ++t_idx) {
        memcpy(d_p[t_idx], s_a[t_idx], m << 3);
    }

    int revK = 0, cnt = 0;
    for (int temp = K; temp; temp >>= 1) {
        revK = (revK << 1) | (temp & 1);
        ++cnt;
    }
    --cnt;
    revK >>= 1;

    for (; cnt; --cnt, revK >>= 1) {
        for (int t_idx = 0; t_idx <= n; ++t_idx) {
            memset(t[t_idx], 0, m << 3);
        }

        for (int a = 0; a <= n; ++a) {
            for (int b = 0; a + b <= n; ++b) {
                u64* f = t[a + b];
                const u64* g = d_p[a];
                const u64* h = d_p[b];
                for (int j = 0; j < m; ++j) {
                    f[j] += g[j] * h[j];
                }
            }
        }

        for (int t_idx = 0; t_idx <= n; ++t_idx) {
            for (int j = 0; j < m; ++j) {
                d_p[t_idx][j] = t[t_idx][j] % P;
            }
        }

        if (revK & 1) {
            for (int t_idx = 0; t_idx <= n; ++t_idx) {
                memset(t[t_idx], 0, m << 3);
            }

            for (int a = 0; a <= n; ++a) {
                for (int b = 0; a + b <= n; ++b) {
                    u64* f = t[a + b];
                    const u64* g = d_p[a];
                    const i64* h = s_a[b];
                    for (int j = 0; j < m; ++j) {
                        f[j] += g[j] * h[j];
                    }
                }
            }

            for (int t_idx = 0; t_idx <= n; ++t_idx) {
                for (int j = 0; j < m; ++j) {
                    d_p[t_idx][j] = t[t_idx][j] % P;
                }
            }
        }
    }

    for (int t_idx = 0; t_idx <= n; ++t_idx) {
        memcpy(s_c[t_idx], d_p[t_idx], m << 3);
    }

    for (int t_idx = 0; t_idx <= n; ++t_idx) {
        i64* arr = s_c[t_idx];
        for (int len = 2; len <= m; len <<= 1) {
            for (int j = 0, step = len >> 1; j < m; j += len) {
                for (int k = 0; k < step; ++k) {
                    arr[j + k + step] -= arr[j + k];
                }
            }
        }
        for (int j = 0; j < m; ++j) {
            arr[j] = (arr[j] % P + P) % P;
        }
    }

    i64 ans = (total - s_c[n][(1 << n) - 1] * fact[L] % P + P) % P;
    cout << ans << '\n';

    return 0;
}
